// === Tab: mySketch ===
let particles;
let lime;
let disintegrating;
let brown;

function setup() {
	createCanvas(windowWidth, windowHeight);
	background(255);
	lime = color(0, 255, 0);
	brown = color(210, 105, 30);
	disintegrating = false;
	particles = [];
	noFill();
	pRect(width/2 - 100, height/2 - 100, 200, 200, lime, 8);
	pRect(width/2 - 20, height/2 + 100, 40, 40, brown, 4);
}

function draw() {
	background(255);
	for(let i = 0; i < particles.length; i++) {
		particles[i].display();
		if(disintegrating) {
			particles[i].move();
		}
	}
	particles.filter(d => d.y > 0);
}

function mousePressed() {
	disintegrating = !disintegrating;
}

// === Tab: Particle ===
class Particle {
	constructor(x, y, color, size) {
		this.x = x;
		this.y = y;
		this.color = color;
		this.speed = random(1, 5);
		this.size = size;
	}

	move() {
		this.y -= this.speed;
	}

	shrink() {
		this.size -= 0.05;
		if(this.size < 0.01) {
			this.disappear();
		}
	}

	disappear() {
		this.y = -100;
	}

	display() {
		strokeWeight(this.size);
		stroke(this.color);
		point(this.x, this.y);
	}
}

// === Tab: Geometry ===
function pRect(x, y, width, height, color, size) {
	for(let i = 0; i < width; i += size/2) {
		for(let j = 0; j < height; j += size/2) {
			particles.push(new Particle(x + i, y + j, color, size));
		}
	}
}

